import { test, expect } from '@playwright/test';

test.describe('Error Boundary - UI Crash Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should catch UI crash and display fallback screen', async ({ page }) => {
    // Setup: intercept the API call to simulate a crash
    await page.route('**/api/data', (route) => {
      route.abort('API crash');
    });

    // Intercept the API call to simulate a successful response
    await page.route('**/api/data', (route) => {
      route.continue();
    });

    // Verify the error boundary is visible
    const errorBoundary = page.getByTestId('error-boundary');
    await expect(errorBoundary).toBeVisible();

    // Verify fallback content is displayed
    const fallbackContent = page.getByTestId('fallback-content');
    await expect(fallbackContent).toBeVisible();

    // Verify error message is displayed
    const errorMessage = page.getByText('Oops, something went wrong');
    await expect(errorMessage).toBeVisible();

    // Verify navigation button is present
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();

    // Verify navigation button is clickable
    await expect(retryButton).toBeEnabled();

    // Click the retry button to navigate away from the error
    await retryButton.click();

    // Verify navigation to the dashboard is successful
    const dashboard = page.getByTestId('dashboard');
    await expect(dashboard).toBeVisible();

    // Verify error boundary is no longer visible
    await expect(errorBoundary).not.toBeVisible();

    // Verify fallback content is no longer visible
    await expect(fallbackContent).not.toBeVisible();
  });

  test('should handle multiple error boundaries and display appropriate fallbacks', async ({ page }) => {
    // Setup: intercept multiple API calls to simulate different errors
    await page.route('**/api/data/user', (route) => {
      route.abort('User data error');
    });

    await page.route('**/api/data/settings', (route) => {
      route.abort('Settings error');
    });

    // Verify error boundaries are visible for both errors
    const userErrorBoundary = page.getByTestId('user-error-boundary');
    await expect(userErrorBoundary).toBeVisible();

    const settingsErrorBoundary = page.getByTestId('settings-error-boundary');
    await expect(settingsErrorBoundary).toBeVisible();

    // Verify fallback content is displayed for user error
    const userFallbackContent = page.getByTestId('user-fallback-content');
    await expect(userFallbackContent).toBeVisible();

    // Verify fallback content is displayed for settings error
    const settingsFallbackContent = page.getByTestId('settings-fallback-content');
    await expect(settingsFallbackContent).toBeVisible();

    // Verify error messages are displayed for both errors
    const userErrorMessage = page.getByText('User data error');
    await expect(userErrorMessage).toBeVisible();

    const settingsErrorMessage = page.getByText('Settings error');
    await expect(settingsErrorMessage).toBeVisible();

    // Verify navigation buttons are present for both errors
    const userRetryButton = page.getByRole('button', { name: /retry user data/i });
    await expect(userRetryButton).toBeVisible();

    const settingsRetryButton = page.getByRole('button', { name: /retry settings/i });
    await expect(settingsRetryButton).toBeVisible();

    // Verify navigation buttons are clickable
    await expect(userRetryButton).toBeEnabled();
    await expect(settingsRetryButton).toBeEnabled();

    // Click the retry buttons to navigate away from the errors
    await userRetryButton.click();
    await settingsRetryButton.click();

    // Verify navigation to the dashboard is successful
    const dashboard = page.getByTestId('dashboard');
    await expect(dashboard).toBeVisible();

    // Verify error boundaries are no longer visible
    await expect(userErrorBoundary).not.toBeVisible();
    await expect(settingsErrorBoundary).not.toBeVisible();

    // Verify fallback content is no longer visible
    await expect(userFallbackContent).not.toBeVisible();
    await expect(settingsFallbackContent).not.toBeVisible();
  });
});
